%[text] ## Local Helper Functions
function ChemicalFormula(str, vars, values)
%-------------------------------------------------------------------------
% Local functions written by Oliver Kluge
%-------------------------------------------------------------------------
    function str = replaceVar(str, vars, values)
        vars = string(vars); values = string(values);
        str = replace(str, vars, values);
        str = replace(str, ["+", "==", " *"], [" + ", " == ", "*"]);
        c = char(str);
        p = strfind(c, "1*");
        for k=1:numel(p)
            a = p(k);
            if a == 1 || ~isstrprop(c(a-1), "alphanum")
                c = [c(1:a-1) '##' c(a+2:end)];
            end
        end
        str = replace(string(c), ["*", "=="], [" ", " == "]);
        str = replace(str, "##", "");
        str = replace(str, ["(", ")"], [" ( ", " ) "]);
    end

    function v = textVar(v)
        if v == ""; return; end
        list = isstrprop(v, "alpha");
        if (numel(list) == 1 && list == 1) || (list(1) == 1 && list(2) == 0)
            v = " " + v;
        end
    end

    function symbol = createSymbol(entity)
        % undocumented, subject to changes w/o notice
        symbol = feval(symengine,"output::mathText","`" + entity + "`");
    end
%-------------------------------------------------------------------------
% Main
%-------------------------------------------------------------------------
switch nargin
    case 1
        vars = []; values = [];
    case 3
        if numel(vars) ~= numel(values)
            error("Number of elements must be the same.");
        end
    otherwise
        error("1 or 3 input arguments expected.");

end
str = replaceVar(str, vars, values);
parts = strsplit(str, " ");
parts = arrayfun(@(p) textVar(p), parts);
parts = arrayfun(@(p) "'" + p + "'", parts);
if isMATLABReleaseOlderThan("R2023a")
    parts = replace(parts, "==", " --> ");
    displayFormula(parts);
else
    parts = replace(parts, "'=='", "cequal");
    displayFormula(parts, "cequal", createSymbol("&rarr;"));
end
end

